#!/usr/bin/env python3
"""Replay retained initial header-race defect with a tiny temporary directory.

Held candidate bytes are retained inside this script so the original probe
remains reproducible after source repair. The hook simulates caller mutation
between the initial header check and authenticated snapshot; no project scope,
ledger, marker, spend or protected workload is touched.
"""
import base64
import hashlib
import json
from pathlib import Path
import tempfile
import types

CANDIDATE_SOURCE_PATH = 'scripts/radio_native_v2_historical_storage.py'
CANDIDATE_PIN = {'bytes': 21869, 'sha256': '37d7225a9b24ee0de6002653d4676417b0b2befb5ce32cd071719fc01694d717'}
HELD_SOURCE_BASE64 = ''
raw = base64.b64decode(HELD_SOURCE_BASE64)
if {'bytes': len(raw), 'sha256': hashlib.sha256(raw).hexdigest()} != CANDIDATE_PIN:
    raise ValueError('Retained initial candidate source bytes differ')
module = types.ModuleType('initial_header_race_held_candidate')
module.__file__ = CANDIDATE_SOURCE_PATH
exec(compile(raw, module.__file__, 'exec'), module.__dict__)
with tempfile.TemporaryDirectory(prefix='seti-review-initial-header-race-') as temporary:
    scope = Path(temporary) / 'observed-root'; scope.mkdir()
    row = {'path': '.', 'kind': 'directory', 'metadata': module._metadata(scope.stat())}
    manifest = {'schema': module.MANIFEST_SCHEMA, 'role': 'historical_scope',
        'scope': str(scope), 'rows': [row]}
    changed_manifest = dict(manifest, scope=str(Path(temporary) / 'different-authenticated-root'))
    authenticated_raw = module.canonical(changed_manifest)
    expected_pin = {'bytes': len(authenticated_raw),
        'sha256': hashlib.sha256(authenticated_raw).hexdigest()}
    original_authenticate = module._authenticate
    def simulate_label_mutation(value, expected_pin):
        value['scope'] = changed_manifest['scope']
        return original_authenticate(value, expected_pin)
    module._authenticate = simulate_label_mutation
    output = None; refusal_type = None
    try:
        output = module.observe_retained_scope(scope, manifest, expected_manifest_pin=expected_pin)
    except (ValueError, OSError) as failure:
        refusal_type = type(failure).__name__
    accepted = output is not None
    result = {'schema': 'radio-native-v2-independent-machine-review-initial-header-race-probe-v1',
        'status': 'DEFECT_REPRODUCED' if accepted else 'PROBE_REFUSED',
        'candidate_source_path': CANDIDATE_SOURCE_PATH, 'candidate_source_raw_pin': CANDIDATE_PIN,
        'defect': 'Manifest header checked before authentication snapshot without repeating scope binding afterward',
        'probe_hook': 'Mutate supplied scope label at entry to _authenticate, simulating a concurrent caller mutation',
        'observed_scope': str(scope), 'authenticated_manifest_scope': changed_manifest['scope'],
        'mismatched_scope_accepted': accepted,
        'accepted_manifest_digest_matches_supplied_expected_pin': bool(accepted and output['manifest_sha256'] == expected_pin['sha256']),
        'filesystem_access_was_only_to_tiny_temporary_fixture': True,
        'refusal_type': refusal_type,
        'fixture_directory_removed_at_probe_exit': True,
        'production_sources_modified': False, 'project_marker_or_ledger_modified': False,
        'protected_control_invocations': 0, 'spend_calls': 0, 'telescope_reads': 0,
        'future_lifetime_or_execution_qualified': False,
        'review_is_an_independent_machine_agent_review_not_human_review': True}
print(json.dumps(result, sort_keys=True, separators=(',', ':'), allow_nan=False))
raise SystemExit(0 if accepted else 1)
